// Writes synthetic store-launcher fixtures for the capture scripts and manual tests: a Steam
// folder (library list, app manifests, and cached library art), Epic manifests, folders for GOG,
// Ubisoft, EA, Battle.net, and Microsoft Store games, and registry.json, the registry snapshot the
// scanners read instead of the real registry. Every game is named "Synthetic ..." and every image
// is generated by make-test-cover.cjs; no real store data or art is used.
// Usage: node scripts/make-store-fixtures.cjs OUT_DIR
"use strict";
const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");

const out = path.resolve(process.argv[2] || "");
if (!process.argv[2]) throw new Error("usage: make-store-fixtures.cjs OUT_DIR");
const coverScript = path.join(__dirname, "make-test-cover.cjs");
const write = (file, text) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text);
};
const cover = (file, hue, ...extra) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  execFileSync(process.execPath, [coverScript, file, String(hue), ...extra.map(String)]);
};
const dir = (...parts) => {
  const folder = path.join(out, ...parts);
  fs.mkdirSync(folder, { recursive: true });
  return folder;
};
const vdfPath = (folder) => folder.replace(/\\/g, "\\\\");

// ---- Steam ----
const steam = dir("steam");
const second = dir("steam-library-2");
write(path.join(steam, "steamapps", "libraryfolders.vdf"), `"libraryfolders"
{
\t"0"
\t{
\t\t"path"\t\t"${vdfPath(steam)}"
\t}
\t"1"
\t{
\t\t"path"\t\t"${vdfPath(second)}"
\t}
}
`);
const steamGames = [
  [steam, "3100001", "Synthetic Orbit Racer", 210],
  [steam, "3100002", "Synthetic Frost Keep", 190],
  [second, "3100003", "Synthetic Ember Tactics", 15],
  [second, "3100004", "Synthetic Reef Divers", 175],
  [steam, "3100005", "Synthetic Night Courier", 280],
];
for (const [library, appid, name, hue] of steamGames) {
  const installdir = name.replace(/\s+/g, "");
  dir(path.relative(out, library), "steamapps", "common", installdir);
  write(path.join(library, "steamapps", `appmanifest_${appid}.acf`), `"AppState"
{
\t"appid"\t\t"${appid}"
\t"name"\t\t"${name}"
\t"StateFlags"\t\t"4"
\t"installdir"\t\t"${installdir}"
}
`);
  // Steam's local library art, one cache layout per game (all generated images, saved under
  // Steam's file names): the older flat portrait, the newer client's per-app folder with only a
  // capsule and wide art, a portrait one folder deeper, wide hero art with a logo and no portrait,
  // and a header alone. GameStrike composes portrait covers for the last two.
  const cache = path.join(steam, "appcache", "librarycache");
  const app = path.join(cache, appid);
  const wide = () => {
    cover(path.join(app, "library_hero.jpg"), hue, 930, 300);
    cover(path.join(app, "logo.png"), hue, 640, 220, "--logo");
    cover(path.join(app, "library_header.jpg"), hue, 460, 215);
  };
  switch (appid) {
    case "3100001":
      cover(path.join(cache, `${appid}_library_600x900.jpg`), hue);
      break;
    case "3100002":
      cover(path.join(app, "library_capsule.jpg"), hue);
      wide();
      write(path.join(app, "0123456789abcdef0123456789abcdef01234567.jpg"), "");
      break;
    case "3100003":
      cover(path.join(app, "abc123", "library_600x900.jpg"), hue);
      break;
    case "3100004":
      wide();
      break;
    default:
      cover(path.join(app, "library_header.jpg"), hue, 460, 215);
  }
}
// A redistributable Steam installs alongside games; the scanner skips it.
write(path.join(steam, "steamapps", "appmanifest_228980.acf"), `"AppState" { "appid" "228980" "name" "Steamworks Common Redistributables" "StateFlags" "4" "installdir" "Steamworks Shared" }`);

// ---- Epic Games ----
const manifests = dir("ProgramData", "Epic", "EpicGamesLauncher", "Data", "Manifests");
for (const [app, name] of [["SynthCanyon", "Synthetic Glass Canyon"], ["SynthPilots", "Synthetic Paper Pilots"]]) {
  const folder = dir("epic", app);
  write(path.join(manifests, `${app}.item`), JSON.stringify({
    DisplayName: name,
    AppName: app,
    InstallLocation: folder,
    LaunchExecutable: `${app}.exe`,
    CatalogNamespace: "synthns",
    CatalogItemId: `${app.toLowerCase()}0001`,
    MainGameAppName: app,
    AppCategories: ["public", "games", "applications"],
    bIsIncompleteInstall: false,
  }, null, 2));
}

// ---- registry snapshot for GOG, Ubisoft, EA, Battle.net, and the Microsoft Store ----
const registry = {};
const uninstall = "HKLM\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall";

const gog = dir("gog", "Synthetic Lantern Maze");
write(path.join(gog, "game.exe"), "");
registry["HKLM\\SOFTWARE\\WOW6432Node\\GOG.com\\Games\\1700000001"] = { gameName: "Synthetic Lantern Maze", path: gog, exe: path.join(gog, "game.exe") };

const ubisoft = dir("ubisoft", "Synthetic Signal Tower");
registry["HKLM\\SOFTWARE\\WOW6432Node\\Ubisoft\\Launcher\\Installs\\9001"] = { InstallDir: `${ubisoft.replace(/\\/g, "/")}/` };
registry[`${uninstall}\\Uplay Install 9001`] = { DisplayName: "Synthetic Signal Tower" };

const ea = dir("ea", "Synthetic Rocket Bakery");
write(path.join(ea, "__Installer", "installerdata.xml"), "<DiPManifest><contentIDs><contentID>9900001</contentID></contentIDs></DiPManifest>");
registry["HKLM\\SOFTWARE\\WOW6432Node\\EA Games\\Synthetic Rocket Bakery"] = { "Install Dir": ea, DisplayName: "Synthetic Rocket Bakery" };

const blizzard = dir("battlenet", "Synthetic Hollow Moon");
const client = dir("battlenet", "Battle.net");
write(path.join(client, "Battle.net.exe"), "");
registry[`${uninstall}\\Synthetic Hollow Moon`] = {
  DisplayName: "Synthetic Hollow Moon",
  Publisher: "Blizzard Entertainment",
  InstallLocation: blizzard,
  UninstallString: `"${path.join(out, "Blizzard Uninstaller.exe")}" --lang=enUS --uid=fenris --displayname="Synthetic Hollow Moon"`,
};
registry[`${uninstall}\\Battle.net`] = { DisplayName: "Battle.net", Publisher: "Blizzard Entertainment", InstallLocation: client };

const xbox = dir("xbox", "Synthetic Quiet Lighthouse");
write(path.join(xbox, "MicrosoftGame.config"), `<?xml version="1.0" encoding="utf-8"?>
<Game configVersion="1"><Identity Name="SyntheticQuietLighthouse" Publisher="CN=Synthetic" Version="1.0.0.0"/>
<ShellVisuals DefaultDisplayName="Synthetic Quiet Lighthouse" Square480x480Logo="Logo480.png"/></Game>
`);
write(path.join(xbox, "AppxManifest.xml"), `<?xml version="1.0" encoding="utf-8"?>
<Package><Identity Name="SyntheticQuietLighthouse" Publisher="CN=Synthetic" Version="1.0.0.0"/>
<Applications><Application Id="Game" Executable="game.exe"/></Applications></Package>
`);
cover(path.join(xbox, "Logo480.png"), 330);
registry["HKCU\\Software\\Classes\\Local Settings\\Software\\Microsoft\\Windows\\CurrentVersion\\AppModel\\Repository\\Packages\\SyntheticQuietLighthouse_1.0.0.0_x64__synth0000000"] = { PackageRootFolder: xbox };

write(path.join(out, "registry.json"), JSON.stringify(registry, null, 2));

// ---- a custom program to add with `gamestrike add-program` ----
write(path.join(out, "programs", "Synthetic Tool.exe"), "");
console.log(`Synthetic store fixtures written to ${out}`);
